const root=document.documentElement,themeToggle=document.querySelector("#theme-toggle");function syncThemeButton(){themeToggle.setAttribute("aria-pressed",String("dark"===root.getAttribute("data-theme")))}syncThemeButton(),themeToggle.addEventListener("click",()=>{const e="dark"===root.getAttribute("data-theme")?"light":"dark";root.setAttribute("data-theme",e),syncThemeButton();try{localStorage.setItem("theme",e)}catch(e){}});const navToggle=document.querySelector("#nav-toggle"),siteNav=document.querySelector("#site-nav");function openNav(){siteNav.classList.add("open"),navToggle.setAttribute("aria-expanded","true"),siteNav.querySelector("a").focus()}function closeNav(e=!1){siteNav.classList.remove("open"),navToggle.setAttribute("aria-expanded","false"),e&&navToggle.focus()}navToggle.addEventListener("click",()=>{siteNav.classList.contains("open")?closeNav():openNav()}),siteNav.addEventListener("click",e=>{e.target.closest("a")&&closeNav()}),document.addEventListener("keydown",e=>{"Escape"===e.key&&siteNav.classList.contains("open")&&closeNav(!0)});const cards=document.querySelector(".cards"),reduceMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches;window.addEventListener("load",()=>{setTimeout(()=>cards.removeAttribute("data-loading"),reduceMotion?0:900)}),document.querySelector("#year").textContent=(new Date).getFullYear();